select to_char(run_time,'MM-DD HH24:MI') t, status, details->'timing'->>'durationMs' ms, substring(details->>'response' from '"stageMs":\{[^}]*\}') stage_ms, substring(details->>'response' from '"bridgeTiming":\{.{0,600}') bt from cron_job_audit where run_time >= '2026-11-15 12:30' and run_time < '2026-11-16 12:45' and job_name='/api/v1/db/forge-served-forecast-snapshot' order by run_time
